    "text": "Considere três osciladores massa-mola independentes (1, 2 e 3) de massa m e constantes elásticas k₁, k₂ e k₃, respectivamente. O tempo que o sistema massa-mola 1 leva para completar uma oscilação é igual ao tempo que o sistema massa-mola 2 leva para completar duas oscilações e ao tempo que o sistema massa-mola 3 leva para completar três oscilações. Agora considere um sistema composto por essas mesmas três molas acopladas em série e colocadas para oscilar junto a um objeto de massa 4m. Assinale a alternativa que contém o valor numérico mais próximo da razão entre a frequência do sistema massa-mola 1 e a frequência do sistema massa-mola em série.",
