    "text": "Uma fonte sonora é lançada do ponto 1 indicado na figura e segue uma trajetória balística parabólica emitindo um tom de frequência constante ff. Sejam f1 a f5 as frequências percebidas pelo observador “o\" quando a fonte passa pelos pontos de 1 a 5, respectivamente, indicados na figura. Observações: • os pontos 1 e 5 estão no mesmo plano horizontal; • os pontos 2 e 4 estão na mesma altitude; • o ponto 3 é o de maior altitude na trajetória; • o ponto 1 é aquele imediatamente depois do lançamento; • o ponto 5 é aquele imediatamente antes do choque com o plano horizontal; • o observador “o\" está na mesma vertical do ponto 3; • a fonte emite em todas as direções; • considere a velocidade da fonte muito menor que a do som. Desta forma, podemos afirmar que:",
