    "text": "Na figura, é apresentado um canhão oscilando preso ao teto por duas molas e disparando continuamente elétrons numa região sujeita a um campo magnético constante. Dados: • constante elástica de cada mola: k; • amplitude de oscilação do canhão / par de molas: A; • direção de oscilação do canhão / par de molas: y; • vetor campo magnético: (−B,0,0); • velocidade relativa de disparo dos elétrons em relação ao canhão: (−v,0,0); • massa do elétron: m; • massa do canhão: M; • carga do elétron: −e. Observações: • o canhão oscila no plano xy; • a velocidade inicial de um elétron disparado é obtida ao se somarem vetorialmente os efeitos da oscilação e do canhão parado; • despreze o efeito gravitacional no movimento dos elétrons; • m << M; • despreze as interações elétricas entre os elétrons. Nas condições acima, a maior coordenada z que algum elétron pode alcançar é:",
