    "title": "Composição relativística de velocidades",
    "text": "Na figura, é mostrada a transformação de Lorentz para diversas velocidades (0,3 c a 0,9 c) de um referencial em movimento em relação a um referencial inercial. Essa transformação é usada para calcular a velocidade relativa (eixo vertical) de um outro objeto se movimentando no mesmo sentido do referencial que está em alta velocidade (0,3 c a 0,9 c). Repare que o eixo horizontal exibe uma escala de velocidade em relação ao referencial inercial e o eixo vertical informa a velocidade relativa entre objeto e referencial em movimento. Uma nave X viaja a 0,5 c e atira um foguete Y, no mesmo sentido de seu movimento, a uma velocidade relativa a X de 0,3 c. Por sua vez, o foguete Y atira um projétil Z, também no mesmo sentido dos movimentos, a uma velocidade relativa a Y de 0,1 c. Dado: • velocidade da luz: c. Em relação ao referencial inercial, a velocidade de Z é aproximadamente:",
