    "title": "Energia potencial em órbita elíptica",
    "text": "Para simular a órbita (x(t),y(t)) do satélite de um planeta, no referencial do planeta, utilizou-se um modelo unidimensional com as seguintes equações: x(t) = A cos(ωt); y(t) = B sen(ωt) onde A, B e ω são constantes e t é o instante de tempo. Dados: • massa do planeta: M; • massa do satélite: m, onde m << M; • constante universal de gravitação: G; • C = √(A² − B²); • localização do centro do planeta: (C,0). A diferença entre a maior e a menor energia potencial gravitacional do satélite é:",
