    "text": "Uma lente convergente é construída usando um material de índice de refração n, podendo a sua distância focal f ser calculada usando a equação dos fabricantes de lentes. Um objeto é posicionado no eixo da lente e muito distante da mesma. Observações: • f é proporcional a (n − 1)−1; • n > 1; • seja x tal que |x| << 1, então (1 − x)−1 ≃ 1 + x. Caso haja uma ínfima variação na constituição do índice de refração do material ( n → n + Δn), a variação Δi na posição final da imagem do objeto (i → i + Δi) é, aproximadamente:",
