    "text": "Em uma determinada região esférica do espaço, a distribuição volumétrica de cargas é tal que o campo elétrico em seu interior é o vetor E(r) û_r, onde û_r é o vetor unitário na direção radial e E(r), em V/m, é igual a: E(r) = { A cos(3rπ/(2R)) + (2 − r)²/R − 1, para 0 ≤ r ≤ R; 0, para r > R }, em que A é uma constante, r é a distância até o centro da esfera e R é o raio da esfera, em metros. Observação: • R < 3 m. Com as condições impostas acima, a constante A, em V/m, necessariamente é:",
