    "text": "Em um centro de pesquisa foram desenvolvidos três equipamentos para medições de tempo, comprimento e massa, cujas leituras são Eₜ, E꜀, Eₘ, respectivamente. As curvas de calibração de cada equipamento estão apresentadas na figura. Esses equipamentos foram utilizados para medir o movimento retilíneo uniforme de uma partícula pontual. A medição da massa indicou leitura de 3 contagens, e a medição do movimento mostrou que ele percorreu uma distância entre as posições indicadas pelas contagens 6 e 2, em um intervalo de tempo de 0 a 1 contagens. Pode-se afirmar que a energia cinética da partícula é:",
