    "title": "Velocidade da sombra de uma fonte em queda",
    "text": "Uma fonte luminosa está presa ao teto de um recinto fechado, a uma altura H do solo, conforme mostra a figura. No recinto há um objeto de altura h (h < H/2) a uma distância 2a de uma das paredes. A lâmpada desprende-se, iniciando um movimento de queda livre, e atinge o solo a uma distância 3a da parede. Considere que o efeito de reflexão de luz nas paredes é desprezível e que a fonte de luz é pontual. Assinale a alternativa que apresenta a expressão correta do módulo da velocidade da sombra a partir do instante em que esta começa a ser projetada sobre a parede.",
