    "title": "Período orbital de Marte a partir do tamanho aparente",
    "text": "Na sua obra “Diálogo sobre os Dois Principais Sistemas do Mundo”, Galileu Galilei cita a variação de tamanho aparente de Marte no céu como uma evidência de que os planetas não orbitavam a Terra: Simplício: Mas quais são os indícios de que eles se movem em torno do Sol? Salviati: Isso se conclui, para os três planetas superiores, Marte, Júpiter e Saturno, a partir de eles se encontrarem sempre muito próximos à Terra quando estão em oposição ao Sol, e muito distantes quando estão em conjunção; e estas aproximação e afastamento têm tanta importância que, quando Marte está próximo, vê-se 60 vezes maior que quando está afastadíssimo (MARICONDA, 2011, p. 404). Com base nos dados disponíveis no trecho e sabendo que a razão apontada por Galileu refere-se à área aparente de Marte visto da Terra, assinale a alternativa que contém a melhor estimativa do período de revolução de Marte ao redor do Sol em meses terrestres.",
