    "text": "A espaçonave CEOS passa pelo corpo celeste Al-Quds com velocidade relativa de 0,6c, onde c é a velocidade da luz no vácuo. No instante em que CEOS e Al-Quds estão alinhados, os relógios do comandante da espaçonave (tCEOS) e de um observador situado em Al-Quds (tQUDS) são sincronizados e zerados. A espaçonave emite uma luz muito intensa no instante em que o comandante da espaçonave marca tCEOS = 4 s após sua passagem por Al-Quds. Dado: • c = 3× 10 8 m/s. Observação: • admita o corpo celeste Al-Quds como sendo um referencial inercial e que a espaçonave se movimente sempre em linha reta. Tomando como referencial o observador em Al-Quds, o instante tQUDS do início da emissão da luz pela CEOS e a distância percorrida pela CEOS desde a passagem por Al-Quds até esse instante são, respectivamente:",
