    "title": "Êmbolo em transformação isentrópica acelerada",
    "text": "Considere um recipiente, sobre uma plataforma, sujeito à pressão atmosférica Pₐₜₘ. Esse recipiente contém um volume inicial Vᵢ de um gás monoatômico ideal em equilíbrio e tem um êmbolo de seção transversal de área A e de massa m. Para monitorar a aceleração do sistema, a plataforma foi suspensa por um dinamômetro, como ilustrado na figura. Por causa de uma ação de uma força externa vertical, o êmbolo atinge uma nova posição de equilíbrio. Nessa posição a leitura do dinamômetro indica que a aceleração do sistema é de 1/10 de g para cima. Determine o módulo do deslocamento Δx do êmbolo, com relação ao fundo do recipiente, considerando que a transformação do gás é isentrópica.",
