    "text": "Considere uma máquina térmica que opera com um ciclo termodinâmico composto de quatro etapas: (i) expansão isotérmica, à temperatura Tq, saindo do volume inicial V₀ até o volume final Vf; (ii) resfriamento isocórico de Tq até Tf; (iii) compressão isotérmica, à temperatura Tf, de Vf até V₀; e (iv) aquecimento isocórico de Tf até Tq. A máquina é inicialmente preparada para operar com o ar atmosférico como fluido de trabalho. Sobre esse sistema, são feitas as seguintes afirmações: I. Aumentando-se a razão de expansão, r = Vf/Vi, é possível aumentar o rendimento da máquina mantendo os demais parâmetros fixos. II. Se o fluido de trabalho fosse substituído por um gás nobre, então o rendimento dessa máquina seria aumentado. III. Considerando os parâmetros r = 10, Tf = 300 K e Tq = 900 K, o valor do rendimento da máquina é superior a 50%. Sobre as afirmações I, II e III pode-se afirmar que",
