    "title": "Registro fotográfico com polarizadores",
    "text": "Considere um filtro polarizador linear no plano S, cuja polarização é paralela ao eixo x. Uma onda eletromagnética com polarização linear no eixo z propaga-se na direção do eixo y. Um pêndulo é colocado na frente do filtro. A ponta do pêndulo contém uma pequena placa circular feita de um filtro de polarização linear. Quando o pêndulo está em repouso, a polarização é paralela ao eixo x. O pêndulo oscila no plano S′, de −90° a 90°, conforme mostra a figura. Uma chapa fotográfica capaz de absorver a onda eletromagnética é colocada atrás dos filtros de polarização. Despreze efeitos de difração e interferência. Considere que os planos S e S′ são paralelos ao plano xz. Assinale a alternativa que melhor representa o que vai ser visto na chapa fotográfica.",
