    "title": "Circuito equivalente de uma membrana neuronal",
    "text": "Em vários ramos da ciência e da engenharia, sistemas de interesse são modelados por circuitos elétricos a eles equivalentes. Na biologia, por exemplo, a membrana de um neurônio é modelada por elementos de circuitos elétricos. Considere apenas as seguintes características: I. A membrana neuronal é constituída de duas camadas de lipídeos que separam os meios condutores intra e extracelular por uma fina camada isolante. II. As proteínas que cruzam a membrana de um neurônio atuam como poros, canais iônicos não seletivos. Com base nessas considerações, o sistema, entre o interior e o exterior da membrana, pode ser representado pelos seguintes elementos de circuitos elétricos:",
    "options": [
      "resistores e fontes de corrente conectados em série",
      "fontes de corrente e capacitores conectados em paralelo",
      "fontes de corrente e capacitores conectados em série",
      "resistores e capacitores conectados em série",
      "resistores e capacitores conectados em paralelo"
    ],
    "answer": 4,
    "answerLabel": "E",
    "status": "Importada",
    "video": "",
