    "title": "Energia cinética em campos gravitacional e magnético",
    "text": "Considere um sistema de coordenadas x, y, z com respectivos vetores de base {î, ĵ, k̂}, sendo z a coordenada vertical. Uma partícula de massa m e carga elétrica de módulo q é colocada em movimento no vácuo, com velocidade v⃗ = v senθ î − v cosθ k̂, em um espaço tridimensional. Nesse espaço, existem um campo magnético uniforme, B⃗ = Bî, e um campo gravitacional constante, g⃗ = −gk̂. O ângulo θ é escolhido de tal forma que a energia cinética da partícula seja conservada. Dadas essas informações, é possível inferir que a energia cinética da partícula é igual a",
