    "title": "Flutuação de cubo com óleo e ar",
    "text": "Um cubo de arestas de comprimento L é fabricado a partir de uma chapa metálica fina de densidade superficial de massa S. O cubo encontra-se bem vedado e possui 20% de seu volume interior preenchido com óleo e o restante preenchido com ar. Em certo momento, o cubo é colocado dentro de um reservatório de água e permanece em equilíbrio na posição ilustrada na figura. Dados: • massa específica da água: 1 g/cm³; • massa específica do óleo: 0,8 g/cm³. Observações: • a massa do ar no interior do cubo é desprezível; • a espessura da chapa é desprezível em relação ao comprimento L das arestas; • a unidade de L é cm; • a unidade de S é g/cm². A relação L/S, em cm³/g, é:",
