    "title": "Aquecimento contínuo de tanque",
    "text": "Na figura mostra-se um tanque sendo alimentado por uma bomba d’água, um agitador e um sistema de aquecimento. Dados: • massa específica da água: 1 g/cm³; • calor específico da água: 1 cal/(g.°C); • vazão de água da bomba: 10 L/min; • 1 cal = 4,2 J. Observações: • não há perdas de calor pelo tanque; • toda energia dissipada pela resistência aquece a água; • o agitador mistura toda a água do tanque, mantendo-a numa mesma temperatura. A água do tanque e a fornecida pela bomba encontram-se a 20 °C. Em determinado instante, o tanque contém 220 L de água e a chave S do sistema de aquecimento é fechada. O tempo, em minutos, para que a água do tanque atinja 60 °C será:",
