    "title": "Efeito Doppler relativístico",
    "text": "Um físico pilotando uma espaçonave foi multado por avanço de um semáforo de trânsito interestelar. Em sua defesa, alegou que via luz verde ao avançar o semáforo. Além de ter sua defesa indeferida, o físico ainda recebeu outra multa por excesso de velocidade. Dados: • velocidade da luz no vácuo: c; • comprimento de onda da cor verde (“siga\"):λg; • comprimento de onda da cor vermelho (“pare\"): λr. A velocidade mínima da espaçonave era:",
