    "title": "Isolamento térmico de parede",
    "text": "Figura 1 Figura 2 Considere uma parede plana que apresenta temperaturas conhecidas e distintas em suas superfícies A e B (Figura 1), respectivamente iguais a T_A1 e T_B1. De modo a minimizar a taxa de transferência de calor, decide-se recobrir a superfície B com uma película isolante. Dados: • espessura da parede: 10 cm; • espessura da película isolante: 6 mm; • razão entre a taxa de transferência de calor da parede recoberta com a película isolante e a taxa de transferência de calor na situação não isolada: 0,4. Observações: • com o recobrimento da superfície B (Figura 2), suponha as temperaturas externas iguais a T_P (lado da película) e a T_A2; • a taxa de transferência de calor é constante ao longo das paredes nas duas situações. Para garantir-se T_B1 − T_A1 = T_P − T_A2, a razão entre as condutividades térmicas da película isolante e do material da parede é:",
