    "title": "Velocidade relativa de partículas",
    "text": "Duas partículas A e B de massas iguais se deslocam no plano XY. As coordenadas de suas posições, em função do instante de tempo t, em que 0 ≤ t ≤ tchoque, são, respectivamente, S_A=(t²−9t+13, t−2) e S_B=(−2t+3, t²−7t+13). No instante t = tchoque, as partículas chocam-se elasticamente. Imediatamente após o choque, o módulo da soma de seus vetores de velocidade é:",
