    "title": "Redefinição das unidades básicas do SI",
    "text": "Em 2019, no 144º aniversário da Convenção do Metro, as unidades básicas do SI foram redefinidas pelo Escritório Internacional de Pesos e Medidas (BIPM). A seguir, são feitas algumas afirmações sobre as modificações introduzidas pela redefinição de 2019. 1. São apenas sete as constantes da natureza definidas como exatas, a saber: a velocidade da luz (c), a frequência de transição de estrutura hiperfina do Césio-133 (ΔνCs), a constante de Planck (h), a carga elementar (e), a constante de Boltzmann (kB), o número de Avogrado (NA) e a eficácia luminosa da radiação monocromática na frequência de 540 THz (Kcd). 2. São apenas seis as constantes da natureza definidas como exatas, a saber: a velocidade da luz (c), a constante de Planck (h), a carga elementar (e), a constante de Boltzmann (kB), o número de Avogrado (NA) e a eficácia luminosa da radiação monocromática na frequência de 683 THz (Kcd). 4. O protótipo de platina e irídio, conservado como padrão do kg, tornou-se obsoleto e o quilograma passou a ser definido apenas em termos de constantes fundamentais exatas. 8. As sete unidades básicas na redefinição do SI são: segundo, metro, quilograma, coulomb, mol, Kelvin e candela. Assinale a alternativa que contém a soma dos números correspondentes às afirmações verdadeiras.",
