    "title": "Içamento subaquático com balão",
    "text": "Um objeto de formato cúbico, com aresta de comprimento L e de massa específica μ_obj, encontra-se apoiado no fundo do mar, devendo ser içado por meio de um balão de borracha de massa m_b, que apresenta volume interno V de ar ajustável. A figura ilustra a situação descrita, com o centro do balão posicionado a 10 m de profundidade. O volume V do balão, em m³, relaciona-se com a diferença de pressão Δp, em atm, entre a pressão interna e a externa do balão pela seguinte equação: Δp = 1,4V² − 1,2V + 1,8 para 1 ≤ V ≤ 3. Dados: • massa do balão: m_b = 50 kg; • massa do cabo: m_c = 100 kg; • comprimento da aresta do objeto cúbico: L = 1 m; • aceleração da gravidade: g = 10 m/s²; • massa específica do objeto: μ_obj = 2850 kg/m³; • massa específica da água: μ_água = 1000 kg/m³; e • 1 atm = 10⁵ Pa. Observações: • o ar acima da superfície da água encontra-se a 1 atm de pressão; • desconsidere o volume do cabo e a massa do ar internamente ao balão; e • para efeito do cálculo da pressão hidrostática sobre o balão, considere que todo o volume V esteja posicionado na mesma profundidade de seu centro. A pressão interna mínima do balão, em atm, a partir da qual será iniciado o movimento do objeto é:",
