    "title": "Colisão entre planetas",
    "text": "Um planeta P₁ foi arremessado de sua órbita original O₁ ao redor de sua estrela S₁ no Sistema Solar 1 e desde então vaga pelo Universo com velocidade constante v₁. Em um determinado momento, ao passar pelo Sistema Solar 2, P₁ se choca frontalmente com um planeta P₂, que se encontra no afélio de sua órbita O₂ em torno de sua única estrela, S 2. O choque entre os dois planetas é perfeitamente inelástico e resulta na criação de um novo planeta P₃. Dados: • módulo da velocidade tangencial de P₂ no afélio de O₂:v₂; • módulo da velocidade de P₁:v₁ = 3v₂; • massa de P₁ = 10⁻⁸ × massa da estrela S₂; e • massa de P₂ = massa de P₁. Sobre a órbita O₃ de P₃ em torno de S₂, é verdadeiro afirmar que:",
