      "o período de sua órbita O 3 é menor que o da órbita O2 de P2.",
      "não haverá órbita O 3, pois o planeta P3 irá de encontro à estrela S2.",
      "não haverá órbita O 3, pois o planeta P3 escapará de sua órbita em torno de S2."
