    "text": "Um recipiente, de seção de área constante e igual a A, é preenchido por uma coluna de líquido de densidade ρ e altura H. Sobre o líquido encontra-se um pistão de massa M, que pode se deslocar verticalmente livre de atrito. Um furo no recipiente é feito a uma altura h, de tal forma que um filete de água é expelido conforme mostra a figura. Assinale a alternativa que contém o alcance horizontal D do jato de água.",
