    "text": "Um violão é um instrumento sonoro de seis cordas de diferentes propriedades, fixas em ambas as extremidades, acompanhadas de uma caixa de ressonância. Diferentes notas musicais são produzidas tangendo uma das cordas, podendo-se ou não alterar o seu comprimento efetivo, pressionando-a com os dedos em diferentes pontos do braço do violão. A respeito da geração de sons por esse instrumento são feitas quatro afirmações: I. Cordas mais finas, mantidas as demais propriedades constantes, são capazes de produzir notas mais agudas. II. O aumento de 1,00% na tensão aplicada sobre uma corda acarreta um aumento de 1,00% na frequência fundamental gerada. III. Uma corda de nylon e uma de aço, afinadas na mesma frequência fundamental, geram sons de timbres distintos. IV. Ao pressionar uma corda do violão, o musicista gera um som de frequência maior e comprimento de onda menor em comparação ao som produzido pela corda tocada livremente. Considerando V como verdadeira e F como falsa, as afirmações I, II, III e IV são, respectivamente,",
