    "text": "Três esferas metálicas maciças E₁, E₂ e E₃, feitas de um mesmo material e de raios R₁, R₂ e R₃, respectivamente, podem trocar cargas elétricas entre si a partir do acionamento de contatos elétricos. Inicialmente apenas E₁ encontra-se eletricamente carregada. Em um primeiro momento estabelece-se contato elétrico entre E₁ e E₂, que é cortado quando o sistema atinge o equilíbrio elétrico. A seguir, estabelece-se contato entre E₂ e E₃. Ao final do processo, observa-se que a carga elétrica líquida das três esferas é igual. Desprezando a capacitância mútua entre as esferas, assinale a proporção entre as massas de E₁, E₂ e E₃, respectivamente.",
