    "title": "Máquinas de Carnot acopladas",
    "text": "Analise as afirmativas abaixo, referentes ao funcionamento de duas máquinas de Carnot, em que uma é ciclo motor e a outra, ciclo de refrigeração. 1: Levando em conta as temperaturas dos reservatórios térmicos e supondo que 80% da potência disponibilizada do ciclo motor seja empregada para o acionamento do ciclo de refrigeração, a quantidade de calor removida da fonte fria nesse ciclo será 120 kJ/min. 2: Considerando apenas o ciclo motor, se a temperatura da fonte fria for duplicada e, simultaneamente, a temperatura da fonte quente for quadruplicada, o motor térmico violará a Segunda Lei da Termodinâmica. 3: Se a temperatura da fonte quente do ciclo motor for modificada para 500 K, a quantidade máxima de calor removido da fonte fria do ciclo de refrigeração terá o mesmo valor numérico do apresentado na Afirmativa 1. Dados: • temperaturas, respectivamente, da fonte quente e da fonte fria do ciclo motor: 600 K e 300 K; • temperaturas, respectivamente, da fonte quente e da fonte fria do ciclo de refrigeração: 300 K e 268 K; e • calor adicionado à máquina térmica do ciclo motor: 2400/67 kJ/min. Considerando que a operação do refrigerador térmico é efetuada pela potência disponibilizada pelo motor térmico, está(ão) correta(s) a(s) afirmativa(s)",
