    "title": "Fusão de gelo sobre gangorra",
    "text": "Um corpo de gelo está disposto na extremidade de uma gangorra que possui uma barra de comprimento C, cuja massa é uniformemente distribuída. Inicialmente, o sistema está em repouso, conforme mostra a figura acima. Em t = 0, o gelo é aquecido por um resistor de resistência R, percorrido por uma corrente elétrica contínua i. Dados: • calor latente de fusão do gelo = L_f; • massa da barra da gangorra: m; e • massa inicial do bloco de gelo: 4m. Considerando que a água proveniente do gelo não se acumula na gangorra e que todo o calor proveniente do aquecimento da resistência é empregado para aquecer o gelo, o instante de tempo t em que a barra iniciará seu movimento será:",
