    "text": "Um projétil de massa m é disparado com velocidade v contra dois blocos A e B, de massas M_A = 800m e M_B = 199m, que estão inicialmente em repouso, um sobre o outro, conforme mostra a figura. O projétil atinge o bloco A, fazendo o conjunto se movimentar de uma distância d, da posição O até a posição D. Considerando g a aceleração da gravidade local, o coeficiente de atrito estático mínimo μ_e entre os blocos, de modo que o bloco B não deslize sobre o bloco A, é:",
