    "title": "Lançamento de carga em campo magnético",
    "text": "Uma partícula de massa m e carga q positiva é lançada obliquamente com velocidade v₀ e ângulo α com a horizontal, conforme a figura. Em certo instante t₁, antes de alcançar a altura máxima de sua trajetória, quando está a uma distância horizontal x₁ do ponto de lançamento, a partícula é submetida a um campo magnético de intensidade B, na direção vertical. Considerando g a aceleração da gravidade local, a menor intensidade B do campo magnético para que a partícula atinja o solo na posição (x₁, 0) é:",
