    "level": "Difícil",
    "title": "Pulsos em tecido balístico",
    "text": "Figura 1 - Vista superior imediatamente antes do impacto. Figura 2 - Vista superior após o impacto. Um projétil atinge um colete balístico sem perfurá-lo. A ação da fibra do tecido balístico no projétil está representada na figura acima. A deformação da fibra é transmitida pela propagação de pulsos longitudinais e transversais que se afastam radialmente do ponto de impacto, em que o projétil produz uma deformação em forma de cone no tecido. O pulso longitudinal, que se propaga ao longo da fibra, faz com que ela se deforme, afinando na direção radial. O pulso transversal, que se propaga com velocidade menor que a velocidade longitudinal, está associado à depressão. À medida que o projétil penetra no tecido, o raio r da depressão aumenta fazendo com que o material do colete se mova na mesma direção do projétil, mantendo o ângulo θ. Sabe-se que a velocidade do projétil logo após atingir o colete é dada pela função horária v(t) = 250 − 5 × 10⁶t [m/s]. Dados: • velocidade do projétil antes do impacto: 250 m/s; • velocidade do pulso longitudinal na fibra: 2000 m/s; e • ângulo θ = 60°. No instante em que a velocidade do projétil for nula, os raios aproximados das regiões deformadas pelo pulso transversal (r) e pelo longitudinal (R), são, respectivamente:",
