    "text": "Considere uma teoria na qual a força de interação entre duas “cargas generalizadas” q₁ e q₂ em universos N-dimensionais é expressa por Fₑ = q₁q₂/(κrᴺ⁻¹), em que κ é uma constante característica do meio. A teoria também prevê uma força entre dois “polos generalizados” p₁ e p₂ expressa por Fₘ = p₁p₂/(μrᴺ⁻¹), na qual μ é outra constante característica do meio. Sabe-se ainda que um polo p pode interagir com uma corrente de carga, i, gerando uma força F = ip/rᴺ⁻². Em todos os casos, r representa a distância entre os entes interagentes. Considerando as grandezas fundamentais massa, comprimento, tempo e corrente de carga, assinale a alternativa que corresponde à fórmula dimensional de κμ.",
