    "text": "Três esferas idênticas de massa m, carga elétrica Q e dimensões desprezíveis, são presas a extremidades de fios isolantes e inextensíveis de comprimento l. As demais pontas dos fios são fixadas a um ponto P, que sustenta as massas. Na condição de equilíbrio do sistema, verifica-se que o ângulo entre um dos fios e a direção vertical é θ, conforme mostra a figura. Sendo ε₀ a permissividade elétrica do meio, o valor da carga elétrica Q é dada por",
