    "title": "Rendimento de três máquinas térmicas acopladas",
    "text": "Considere um sistema de três máquinas térmicas M₁, M₂ e M₃ acopladas, tal que o rejeito energético de uma é aproveitado pela seguinte. Sabe-se que a cada ciclo, M₁ recebe 800 kJ de calor de uma fonte quente a 300 K e rejeita 600 kJ, dos quais 150 kJ são aproveitados por M₂ para realização de trabalho. Por fim, M₃ aproveita o rejeito de M₂ e descarta 360 kJ em uma fonte fria a 6 K. São feitas as seguintes afirmações: I. É inferior a 225 K a temperatura da fonte fria de M₁. II. O rendimento do sistema é de 55%. III. O rendimento do sistema corresponde a 80% do rendimento de uma máquina de Carnot operando entre as mesmas temperaturas. Conclui-se então que",
