    "text": "Uma fonte sonora de frequência f0 é arremessada verticalmente para cima, com velocidade inicial v0, de um ponto da superfície terrestre no qual a aceleração da gravidade é g. Dados: • aceleração da gravidade: g = 9,8 m/s²; e • velocidade inicial da fonte sonora: v0 = 98 m/s. Nota: despreze a resistência do ar e a variação da aceleração da gravidade com a altitude. A frequência f percebida 10 segundos mais tarde por um observador estático situado no local do arremesso é tal que",
