    "title": "Intensidade de luz linearmente polarizada",
    "text": "Um indivíduo instalou na roda do carro uma fonte monocromática linearmente polarizada, irradiando em direção ortogonal à roda e paralela ao solo. O veículo está em movimento retilíneo uniforme. Um detector linearmente polarizado acompanha o eixo da roda com a mesma velocidade e no mesmo sentido do carro. O gráfico da intensidade luminosa Iₗ captada pelo detector em função do ângulo θ entre os planos de polarização da luz e do detector é:",
