    "title": "Velocidade de carga em campos eletrostáticos",
    "text": "Uma partícula com carga positiva viaja em velocidade constante até aproximar-se de uma esfera oca com carga negativa uniformemente distribuída em sua casca. Ao encontrar a esfera, a partícula entra em seu interior por um pequeno furo, passa pelo centro e deixa a esfera por um segundo furo, prosseguindo o movimento. Bem distante da esfera, a partícula se aproxima de uma placa metálica plana de grande dimensão, com carga negativa uniformemente distribuída pela placa, conforme esquema da figura. Observações: • a carga da partícula não redistribui a carga da casca esférica e nem da placa plana; e • a distribuição das cargas da casca esférica e da placa plana não interferem entre si. O gráfico que melhor exprime a velocidade da partícula em função de sua posição é:",
