    "title": "Interferência em películas e espelhos",
    "text": "Uma fonte luminosa A emite no vácuo luz de comprimento de onda λ = 500 nm em direção a um anteparo em C. Em frente ao espelho B há uma película P₁ de índice n₁ = 1,25 e, em frente ao espelho D, uma película P₂ de índice n₂. Os espelhos equidistam do centro do anteparo C. Após sair de A, um feixe reflete em direção a B e outro refrata em direção a D; após refletir em B, o feixe refrata diretamente para E; após refletir em D, o outro feixe sofre reflexão total em C e segue para E. O menor índice n₂ para ocorrer interferência totalmente destrutiva para um observador em E é:",
