    "title": "Rendimento de máquinas térmicas",
    "text": "Um escritório de patentes analisa as afirmativas de um inventor que deseja obter os direitos sobre três máquinas térmicas reais que trabalham em um ciclo termodinâmico. Os dados sobre o calor rejeitado para a fonte fria e o trabalho produzido pela máquina térmica – ambos expressos em Joules – encontram-se na tabela abaixo. Máquina Térmica Calor Rejeitado [J] Trabalho Produzido [J] A 40 60 B 15 30 C 8 12 As afirmativas do inventor são: Afirmativa 1: O rendimento das máquinas A e C são os mesmos para quaisquer temperaturas de fonte quente e de fonte fria. Afirmativa 2: As máquinas A, B e C obedecem à Segunda Lei da Termodinâmica. Afirmativa 3: Se o calor rejeitado nas três situações acima for dobrado e se for mantida a mesma produção de trabalho, a máquina B apresentará rendimento superior aos das máquinas A e C, supondo atendidos os princípios da termodinâmica. Tomando sempre as temperaturas dos reservatórios das fontes quente e fria das máquinas como 900 K e 300 K, está(ão) correta(s) a(s) afirmativa(s):",
