    "text": "Um foguete desloca-se com aceleração constante a, que forma um ângulo α com a vertical, como mostra a figura, em uma região cujo campo gravitacional local é g. No interior do foguete há um pêndulo simples de comprimento L. Na condição de equilíbrio, o período τ do pêndulo para oscilações de pequenas amplitudes é dado por uma das expressões abaixo. Observação: as dimensões do corpo preso ao pêndulo são desprezíveis em relação ao seu comprimento.",
