    "text": "Considere duas partículas de massa m, cada qual presa numa das pontas de uma corda, de comprimento ℓ e massa desprezível, que atravessa um orifício de uma mesa horizontal lisa. Conforme mostra a figura, a partícula sobre a mesa descreve um movimento circular uniforme de raio r e velocidade angular ω₁. A partícula suspensa também descreve esse mesmo tipo de movimento, mas com velocidade angular ω₂, estando presa a uma mola de constante elástica k e comprimento natural desprezível, mantida na horizontal. Sendo g o módulo da aceleração da gravidade e θ o ângulo do trecho suspenso da corda com a vertical, a razão (ω₂/ω₁)² é dada por",
