    "text": "Uma bola é deixada cair conforme mostra a figura. Inicialmente, ela gira com velocidade angular ω no sentido anti-horário para quem a observa do leste, sendo nula a velocidade do seu centro de massa. Durante a queda, o eixo de rotação da bola permanece sempre paralelo à direção oeste-leste. Considerando o efeito do ar sobre o movimento de queda da bola, são feitas as seguintes afirmações:\nI. A bola está sujeita apenas a forças verticais e, portanto, cairá verticalmente.\nII. A bola adquire quantidade de movimento para o norte (N) ou para o oeste (O).\nIII. A bola adquire quantidade de movimento para o leste (L) ou para o sul (S).\nIV. Quanto maior for a velocidade angular ω da bola, mais ela se afastará do ponto C.\nEstá(ão) correta(s) apenas",
