    "title": "Emissão termiônica em válvula",
    "text": "Dentro de uma câmara de vácuo encontra-se um filamento F aquecido por meio de uma fonte elétrica externa de d.d.p. V₁. A radiação emitida por F atinge o eletrodo metálico E₁, que passa a emitir elétrons que podem ser coletados no eletrodo E₂, acarretando a corrente I medida num amperímetro. Uma segunda fonte externa, de d.d.p. V₂, é conectada ao circuito conforme ilustrado na figura. Um obstáculo O impede que E₂ receba radiação do filamento F. Analise as seguintes afirmações:\nI. A corrente I aumenta sempre que V₂ aumenta e tende a um valor assintótico Imax.\nII. Toda a radiação que incide em E₁ pode causar ejeção de elétrons.\nIII. Para certo valor V₂ < 0, é possível obter uma corrente I invertida em relação ao sentido mostrado na figura.\nIV. É possível ter I ≠ 0 para V₂ = 0 com I dependente de V₁.\nEstão corretas",
