    "title": "Projeção de lanterna com lente divergente",
    "text": "Uma lanterna cilíndrica muito potente possui uma lente divergente em sua extremidade e projeta luz sobre um anteparo vertical. O eixo central da lanterna e o eixo principal da lente estão alinhados e formam um ângulo de 45° com a horizontal. A lâmpada gera raios paralelos que encontram a lente divergente, formando um feixe cônico na saída. O centro óptico O da lente está aproximadamente alinhado com as bordas frontais da lanterna. A distância horizontal entre o foco F da lente e o anteparo é 1 m. Dados: lente plano-côncava, com a face côncava na parte externa; diâmetro da lanterna d = 10 cm; índice de refração do ar = 1; índice de refração da lente = 1,5; raio de curvatura da face côncava = 2,5√3 cm. O comprimento do semieixo maior do contorno da seção cônica projetada no anteparo, em metros, é:",
