    "title": "Equilíbrio entre empuxo, mola e campo elétrico",
    "text": "Um corpo encontra-se com 2/3 de seu volume submerso. Uma extremidade está presa por uma corda a um conjunto de roldanas que suspende uma carga puntiforme submetida a um campo elétrico uniforme; a outra está presa a uma mola distendida, fixa no fundo do recipiente. O sistema está em equilíbrio conforme a figura. Dados: corda e roldanas ideais; aceleração da gravidade g; massa específica do fluido ρ; massa específica do corpo 2ρ; constante elástica da mola k; volume do corpo V; intensidade do campo elétrico E; massa da carga elétrica m; carga elétrica +q. Desprezando os efeitos de borda no campo elétrico, a deformação da mola no equilíbrio é:",
