    "text": "A figura mostra uma haste de massa desprezível, com um apoio articulado em uma extremidade. Na outra há um recipiente apoiado em uma mola e amarrado ao solo por um fio. A haste é mantida horizontal e a mola comprimida. Uma bola é colocada no recipiente e, após o corte do fio, o sistema é liberado com distensão instantânea da mola. Dados: comprimento da prancha = 1 m; distância do apoio ao cesto = 5 m; massa da bola = 200 g; deformação inicial da mola = 10 cm; g = 10 m/s². Despreze as dimensões da bola. A constante elástica da mola, em N/m, para que, quando a prancha estiver perpendicular ao solo, a bola seja lançada e acerte o cesto é:",
