    "text": "Um manômetro de reservatório é composto por dois tubos verticais comunicantes pelas bases e abertos nas extremidades. O conjunto é parcialmente preenchido por um fluido e, à pressão atmosférica padrão, o nível nos dois tubos é o mesmo. Aplica-se no tubo da esquerda uma pressão manométrica equivalente a 12 mm de coluna de água. Dados: diâmetro do tubo esquerdo = 20 mm; diâmetro do tubo direito = 10 mm; densidade do fluido = 1,2. Sem vazamento, a ascensão do fluido no tubo da direita, em mm, é:",
