    "text": "Duas pessoas executam um experimento para medir o raio da Terra a partir do pôr do Sol. Quando uma pessoa deitada observa o pôr do Sol a partir do nível do mar, outra pessoa, de pé, inicia a contagem do tempo até observá-lo a partir da altura dos seus olhos. O intervalo entre as observações é Δt. Considere a Terra uma esfera perfeita, o eixo de rotação perpendicular ao plano de translação, o experimento realizado na linha do Equador e despreze a translação da Terra. Dados: período de rotação T; distância vertical entre os olhos do segundo observador e o nível do mar h. O raio da Terra obtido é:",
