    "text": "Uma fonte de tensão com força eletromotriz E e resistência interna Rᵢₙₜ = 0,05 Ω, protegida por um fusível, alimenta uma carga por meio de dois cabos com resistência linear de 1 Ω/km, como mostra a Figura 1. A Figura 2 mostra a aproximação da reta característica de operação do fusível. Inicialmente, a carga consome 10 kW e opera com tensão terminal Vₜ = 100 V; subitamente, um curto-circuito entre os cabos faz o fusível abrir o circuito. Sabendo que o tempo de abertura foi 1,25 ms, a energia total dissipada nos cabos, em joules, durante o curto-circuito é aproximadamente:",
