    "text": "Considere quatro cargas fixadas sobre o eixo x orientado para a direita. Duas delas, -q₁ e +q₁, separadas por uma distância a₁, formam o sistema 1; as outras, -q₂ e +q₂, separadas por uma distância a₂, formam o sistema 2. Os sistemas estão separados por uma distância r muito maior que a₁ e a₂, conforme a figura. Considerando (1 + z)⁻² ≈ 1 - 2z + 3z² para z ≪ 1, a força exercida pelo sistema 1 sobre o sistema 2 é",
