    "text": "No livro Teoria do Calor (1871), Maxwell, escreveu referindo-se a um recipiente cheio de ar: “... iniciando com uma temperatura uniforme, vamos supor que um recipienteé dividido em duas partes por uma divisória na qual existe um pequeno orifício, e que um ser que pode ver as moléculas individualmente abre e fecha esse orifício de tal modo que permite somente a passagem de moléculas rápidas de A para B e somente as lentas de B para A. Assim, sem realização de trabalho, ele aumentaraá temperatura de B e diminuirá a temperatura de A em contradição com... ”. Assinale a opção que melhor completa o texto de Maxwell.",
