    "text": "As fibras ópticas funcionam pelo Princípio da Reflexão Total, que ocorre quando os raios de luz que seguem determinados percursos dentro da fibra são totalmente refletidos na interface núcleo-casca, permanecendo no interior do núcleo. Considerando apenas a incidência de raios meridionais e que os raios refratados para a casca são perdidos, e sabendo que os índices de refração do ar, do núcleo e da casca são dados, respectivamente, por n₀, n₁ e n₂ (n₁ > n₂ > n₀), o ângulo máximo de incidência θₐ, na interface ar-núcleo, para o qual ocorre reflexão total no interior da fibra é dado por uma das expressões abaixo. Considerações: raios meridionais são aqueles que passam pelo centro do núcleo; todas as opções correspondem a números reais.",
