    "text": "Considere as afirmações abaixo, relativas a uma máquina térmica que executa um ciclo termodinâmico durante o qual há realização de trabalho. Afirmação I: se as temperaturas das fontes forem 27 °C e 427 °C, a máquina térmica poderá apresentar rendimento de 40%. Afirmação II: se o rendimento da máquina for 40% do rendimento ideal para temperaturas das fontes iguais a 27 °C e 327 °C e se o calor rejeitado pela máquina for 0,8 kJ, o trabalho realizado será 1,8 kJ. Afirmação III: se a temperatura de uma das fontes for 727 °C e se a razão entre o calor rejeitado e o calor recebido for 0,4, a outra fonte apresentará temperatura de −23 °C caso o rendimento da máquina seja 80% do rendimento ideal. Está(ão) correta(s):",
