    "text": "Em um experimento no vácuo, um pulso intenso de laser incide na superfície de um alvo sólido, gerando uma nuvem de cargas positivas, elétrons e átomos neutros. Uma placa metálica, ligada ao terra por um resistor R de 50 Ω, é colocada a 10 cm do alvo e intercepta parte da nuvem, sendo observado no osciloscópio o gráfico da variação temporal da tensão sobre o resistor. Considere as afirmativas: I. A área M no gráfico é proporcional à carga coletada de elétrons, e a área N é proporcional à de cargas positivas. II. A carga total de elétrons coletados é aproximadamente igual, em módulo, à carga total de cargas positivas coletadas, e mede aproximadamente 1 nC. III. Em qualquer instante a densidade de cargas positivas que atinge a placa é igual à de elétrons. Está(ão) correta(s) apenas",
