    "text": "Uma placa é feita de um metal cuja função trabalho W é menor que hν, sendo ν uma frequência no intervalo do espectro eletromagnético visível e h a constante de Planck. Deixada exposta, a placa interage com a radiação eletromagnética proveniente do Sol absorvendo uma potência P. Sobre a ejeção de elétrons da placa metálica nesta situação é correto afirmar que os elétrons",
