    "title": "Força de feixe de projéteis sobre esfera",
    "text": "Considere um feixe homogêneo de pequenos projéteis deslocando-se na mesma direção e na mesma velocidade constante até atingir a superfície de uma esfera que está sempre em repouso. A esfera pode ter um ou dois tipos de superfícies: totalmente refletora, com colisão perfeitamente elástica, e/ou totalmente absorvedora, com colisão perfeitamente inelástica. Em uma das superfícies, o ângulo α da figura pertence ao intervalo [0,β], enquanto na outra superfície α pertence ao intervalo (β,π/2]. Para que a força aplicada pelos projéteis sobre a esfera seja máxima, o(s) tipo(s) de superfície(s) é(são):",
