    "title": "Pressões em manômetro com dois fluidos",
    "text": "Considerando o esquema, um pesquisador faz três afirmações. Afirmação I: se a diferença de pressão entre os reservatórios (Pₐ − Pᵦ) for equivalente a 20 mm de coluna de água, a diferença de massa específica entre os fluidos (ρ₁ − ρ₂) é igual a 0,2 kg/L. Afirmação II: se o fluido 1 for água e a diferença de pressão (Pₐ − Pᵦ) for 0,3 kPa, a massa específica do fluido 2 é igual a 0,7 kg/L. Afirmação III: caso o fluido 1 tenha massa específica igual à metade da massa específica da água, o fluido 3, que substitui o fluido 2 da configuração original, deve ser mais denso do que a água para que a diferença de pressão entre os reservatórios seja a mesma da afirmação I. Dados: massa específica da água = 1 kg/L; g = 10 m/s²; para as afirmações I e II, L₁ = 0,30 m e L₂ = 0,40 m; para a afirmação III, L₁ = 0,60 m e L₂ = 0,80 m. Os fluidos são imiscíveis. Está(ão) correta(s):",
