    "title": "Índice do ar no interferômetro de Michelson",
    "text": "A figura mostra um interferômetro de Michelson adaptado para determinar o índice de refração do ar. As características do padrão de interferência dos dois feixes incidentes no anteparo dependem da diferença de fase entre eles, neste caso influenciada pela cápsula contendo ar. Reduzindo a pressão na cápsula de 1 atm até zero (vácuo), nota-se que a ordem das franjas de interferência sofre um deslocamento de N: a franja de ordem 0 passa a ocupar o lugar da de ordem N, a franja de ordem 1 ocupa o lugar da de ordem N + 1, e assim sucessivamente. Sendo d a espessura da cápsula e λ o comprimento de onda da luz no vácuo, o índice de refração do ar é igual a",
