    "title": "Impureza em cristal semicondutor",
    "text": "É muito comum a ocorrência de impurezas em cristais semicondutores. Em primeira aproximação, a energia de ionização dessas impurezas pode ser calculada num modelo semelhante ao do átomo de hidrogênio. Considere um semicondutor com uma impureza de carga +e atraindo um elétron de carga -e. Devido a interações com os átomos da rede cristalina, o elétron, no semicondutor, possui massa igual a mᵣm₀, em que m₀ é a massa de repouso do elétron e mᵣ uma constante adimensional. O conjunto impureza/elétron está imerso no meio semicondutor de permissividade relativa εᵣ. A razão entre a energia de ionização desta impureza e a energia de ionização do átomo de hidrogênio é igual a",
