    "text": "Um recipiente contém um gás monoatômico ideal inicialmente no estado L, com pressão p e volume V. O gás é submetido a uma transformação cíclica LMNL, absorvendo de uma fonte quente uma quantidade de calor Q₁ e cedendo a uma fonte fria uma quantidade de calor Q₂. Pode-se afirmar que Q₁ é igual a",
