    "text": "Uma corda, de massa desprez ível, tem fixada em cada uma de suas extremidades, F e G, uma partícula de massa m. Esse sistema encontra-se em equilíbrio apoiado numa superfície cil índrica sem atrito, de raio r, abrangendo um ângulo de 90 o e simetricamente disposto em relação ao ápiceP do cilindro, conforme mostra a figura. Se a corda for levemente deslocada e começa a escorregar no sentido anti-horário, o ânguloθ ≡ ∠FOP em que a partícula na extremidade F perde contato com a superfície é tal que",
