    "text": "Em problemas de aproveitamento de energia térmica encontra-se V = kαβ. V tem dimensão de potência/(área×temperatura); α é a taxa de variação de temperatura com a posição; e β é a viscosidade dinâmica, de dimensão (força×tempo)/área. Designando temperatura, comprimento e tempo por θ, L e T, a dimensão de k é:",
