    "text": "Sobre uma mesa sem atrito, uma bola de massa M é presa por duas molas alinhadas, de constante elástica k e comprimento natural ℓ₀, fixadas nas extremidades da mesa. A bola é deslocada uma distância x na direção perpendicular à linha inicial das molas e solta. Obtenha a aceleração da bola usando a aproximação (1 + a)ᵅ = 1 + αa.",
