    "title": "Consistência dimensional da aceleração",
    "text": "Um exercício de dinâmica começa assim: “Uma partícula move-se com aceleração de módulo μ(r + a³/r²), sendo r a distância entre a origem e a partícula. Considere que ela foi lançada a partir da distância a com velocidade inicial 2√(μa).” Existe algum erro conceitual nesse enunciado? Por quê?",
