    "title": "Mola e anteparo acelerado no plano inclinado",
    "text": "No plano inclinado, o corpo de massa m é preso a uma mola de constante elásticak, sendo barrado à frente por um anteparo. Com a mola no seu comprimento natural, o anteparo, de alguma forma, inicia seu movimento de descida com uma aceleração constantea. Durante parte dessa descida, o anteparo mantém contato com o corpo, dele se separando somente após um certo tempo. Desconsiderando quaisquer atritos, podemos afirmar que a variação máxima do comprimento da mola é dada por",
