    "title": "Quadro dilatado suspenso por corda",
    "text": "Um quadro quadrado de lado ℓ e massa m, feito de um material de coeficiente de dilatação superficialβ, é pendurado no pino O por uma corda inextensível, de massa desprezível, com as extremidades fixadas no meio das arestas laterais do quadro, conforme a figura. A força de tração máxima que a corda pode suportar éF. A seguir, o quadro é submetido a uma variação de temperatura ∆ T, dilatando. Considerando desprezível a variação no comprimento da corda devida à dilatação, podemos afirmar que o comprimento mínimo da corda para que o quadro possa ser pendurado com segurança é dado por",
