    "title": "Barra apoiada em semicilindro",
    "text": "Considere um semicilindro de peso P e raio R sobre um plano horizontal não liso, mostrado em corte na figura. Uma barra homogênea de comprimento L e peso Q está articulada no ponto O. A barra está apoiada na superfície lisa do semicilindro, formando um ânguloα com a vertical. Quanto vale o coeficiente de atrito mínimo entre o semicilindro e o plano horizontal para que o sistema todo permaneça em equilíbrio?",
