    "text": "Considere um oscilador harmônico simples composto por uma mola de constante elásticak, tendo uma extremidade fixada e a outra acoplada a uma partícula de massa m. O oscilador gira num plano horizontal com velocidade angular constante ω em torno da extremidade fixa, mantendo-se apenas na direção radial, conforme mostra a figura. ConsiderandoR0 a posição de equilíbrio do oscilador para ω = 0, pode-se afirmar que",
